import com.bridger.momentum.*;
import java.nio.file.*;
import java.util.*;

public final class ServerModeRegression {
    private static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
    private static ReplayData bridge(int gap,int rise){return new ReplayData(Arrays.asList(new ReplayData.Frame(.5,65,.5),new ReplayData.Frame(.5,65+rise,gap+1.5)),Arrays.asList(new ReplayData.Block(0,64,0,1,0,0,false),new ReplayData.Block(0,64+rise,gap+1,1,0,0,false),new ReplayData.Block(0,64,1,24,0,0,true),new ReplayData.Block(0,64+rise,gap,24,0,1,true)),false);}
    public static void main(String[] args)throws Exception{
        for(int rise:new int[]{-3,0,3,4,7})for(int gap:new int[]{16,28})check(ServerMode.detect("MCPLAYHD.NET:25565",ServerMode.measure(bridge(gap,rise)))==(gap==16?ServerMode.Mode.EXTRA_SHORT:ServerMode.Mode.SHORT),"Short incorrectly depends on height");
        check(ServerMode.detect("play.mcplayhd.net",ServerMode.measure(bridge(51,0)))==ServerMode.Mode.NORMAL,"51b is not Normal");check(ServerMode.detect("mcplayhd.net:25566",ServerMode.measure(bridge(83,0)))==ServerMode.Mode.LONG,"83b is not Long");
        for(String host:new String[]{"mcplayhd.nety","notmcplayhd.net","mcplayhd.net.example.org","other.example","Singleplayer",""})check(ServerMode.detect(host,ServerMode.measure(bridge(16,0)))==ServerMode.Mode.UNKNOWN,"McPlay rules leaked to another server: "+host);
        check(ServerMode.detect("mcplayhd.net",new ServerMode.Measurement(true,27,3))==ServerMode.Mode.UNKNOWN,"Unspecified distance was guessed");check(ServerMode.detect("mcplayhd.net",ServerMode.UNAVAILABLE)==ServerMode.Mode.UNKNOWN,"Missing platform evidence was guessed");
        Path root=Files.createTempDirectory("server-modes-");RunHistory history=new RunHistory(root.resolve("saved"));history.add("SUCCESS",3.95,4,"Z",Collections.emptyList(),bridge(28,3),"mcplayhd.net");RunHistory.Run run=history.recent().get(0);history.rename(run,"My short bridge");RunHistory.Run saved=history.saved().get(0);check(saved.modeReady()&&saved.mode()==ServerMode.Mode.SHORT&&saved.name().equals("My short bridge"),"Mode or name was lost after save/reload");RunHistory.Run imported=history.importReplay(history.exportReplay(saved));check(imported.isImported()&&imported.mode()==ServerMode.Mode.SHORT,"Imported replay lost its mode");
        Path file=root.resolve("saved").resolve(run.id+".properties");Properties legacy=new Properties();try(java.io.InputStream in=Files.newInputStream(file)){legacy.load(in);}for(String key:new ArrayList<>(legacy.stringPropertyNames()))if(key.equals("mode")||key.startsWith("mode."))legacy.remove(key);try(java.io.OutputStream out=Files.newOutputStream(file)){legacy.store(out,"legacy metadata fixture");}RunHistory.Run old=history.saved().stream().filter(r->r.id.equals(run.id)).findFirst().get();check(!old.modeReady(),"Legacy summary was guessed without reading its recording");ReplayFolders folders=new ReplayFolders(root.resolve("folders.properties"));folders.fileByServer(history,old);String parent=folders.folderOf(old.id);history.indexModes(Collections.singletonList(old));long limit=System.nanoTime()+5000000000L;while(!old.modeReady()&&System.nanoTime()<limit)Thread.sleep(5);check(old.mode()==ServerMode.Mode.SHORT,"Background index failed to recognize an older replay");folders.fileByServer(history,old);String child=folders.folderOf(old.id);check(folders.label(child).equals("Short")&&folders.parentOf(child).equals(parent)&&folders.matches(old.id,parent),"Mode subfolder migration failed");folders=new ReplayFolders(root.resolve("folders.properties"));check(folders.parentOf(child).equals(parent)&&folders.pathLabel(child).equals("mcplayhd.net / Short"),"Hierarchy did not persist");String personal=folders.create("Personal");folders.move(old.id,personal);folders.fileByServer(history,old);check(folders.folderOf(old.id).equals(personal),"Automatic sorting overwrote a manual move");folders.delete(parent);check(folders.folderOf(old.id).equals(personal)&&!folders.folders().containsKey(child),"Deleting a server did not remove its subtree safely");check(ServerMode.Filter.SHORT.matches(old.mode())&&!ServerMode.Filter.LONG.matches(old.mode())&&ServerMode.Filter.ALL.matches(old.mode()),"Mode filter does not compose correctly");
        System.out.println("PASS: McPlay-only distance modes, height-independent Short, persisted/shared modes and background legacy indexing");
    }
}
